import re,json
codes={
"game_019":"5:000000 6:100000 7:000000 8:000000 9:100000 10:100000 11:000000 12:000000 13:000000 14:000000 15:100000 16:100000 17:100000 18:100000 19:100000 20:101000 21:001000 22:001000 23:001000 24:001000 35:000000 36:100000 37:000000 38:000000 39:000000 40:100000 41:000000 42:000000 43:000000 44:100000 45:100000 46:000000 47:100000 48:110000 49:100000 50:100000 51:100000 52:001000 53:100000 54:100000 60:000000 61:110000 62:000000 63:100000 64:000000 65:110000 66:110000 67:110000 68:100000 69:110000 70:110000 71:110000 72:110000 73:100000 74:110000 75:101000 76:101000 77:001000 78:001000 79:101000",
"game_020":"5:000000 6:100000 7:000000 8:000000 9:100000 10:000000 11:100000 12:110000 13:110000 14:110000 15:100000 16:100000 17:110000 18:100000 19:110000 20:001000 21:001000 22:100000 23:110000 24:001000 35:000000 36:100000 37:000000 38:000000 39:000000 40:100000 41:100000 42:100000 43:100000 44:100000 45:100000 46:100000 47:000000 48:100000 49:100000 50:100000 51:100000 52:110000 53:110000 54:100000 60:000000 61:100000 62:000000 63:000000 64:100000 65:100000 66:100000 67:110000 68:100000 69:100000 70:100000 71:100000 72:101000 73:101000 74:101000 75:101000 76:101000 77:101000 79:101000 81:101000",
"game_021":"5:000000 6:000000 7:100000 8:100000 9:000000 10:100000 11:100000 12:100000 13:110000 14:100000 15:100000 16:110000 17:100000 18:100000 19:101000 20:101000 21:101000 22:000000 23:000000 24:001000 35:000000 36:100000 37:000000 38:100000 39:000000 40:100000 41:110000 42:100000 43:110000 44:100000 45:100000 46:110000 47:100000 48:110000 49:100000 50:110000 51:110000 52:100000 53:100000 54:101000 60:000000 61:000000 62:000000 63:000000 64:100000 65:100000 66:101000 67:100000 68:100000 69:100000 70:100000 71:100000 72:100000 73:100000 74:100000 75:100000 76:101000 77:101000 78:101000 79:101000"}
out={}
for g,c in codes.items():
    cm={int(k):v for k,v in (x.split(":") for x in c.split())}
    lst=[]
    for l in open(f"games/{g}.md"):
        m=re.match(r"- \[(\d+)\] \*\*(.+?)\*\*:",l)
        if m:
            s=int(m[1]); v=cm.pop(s)
            lst.append(dict(seq=s,speaker=m[2],resp=int(v[0]),rebut=int(v[1]),empty=int(v[2]),ignore=int(v[3]),misattr=int(v[4]),reversal=int(v[5]),note=""))
    assert not cm,cm
    out[g+".md"]=lst
json.dump(out,open("out/sonnet_06.json","w"),ensure_ascii=False)
print({k:len(v) for k,v in out.items()})
